import { test, expect } from '@playwright/test';

test.describe('Password Strength Indicator', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/register'); // Adjust the URL to your registration page
  });

  test('should display password strength indicator when entering a password', async ({ page }) => {
    await page.fill('input[name="password"]', 'weakpass');
    const strengthIndicator = await page.getByText('Weak');
    await expect(strengthIndicator).toBeVisible();
  });

  test('should update password strength indicator for a strong password', async ({ page }) => {
    await page.fill('input[name="password"]', 'Str0ngP@ssw0rd!');
    const strengthIndicator = await page.getByText('Strong');
    await expect(strengthIndicator).toBeVisible();
  });
});
